def ws(s): return r"\s+".join(re.escape(w) for w in s.split())
def sub1(old, new):
    global t
    n = len(re.findall(ws(old), t)); assert n == 1, (old[:70], n)
    t = re.sub(ws(old), lambda m: new, t)
def replace_section(heading_prefix, new_text, upto=None):
    """replace from the heading line through the line before the next heading (or the `upto` heading)"""
    global t
    L = t.split("\n")
    a = next(k for k, l in enumerate(L) if l.startswith(heading_prefix))
    if upto: b = next(k for k, l in enumerate(L) if k > a and l.startswith(upto))
    else: b = next(k for k, l in enumerate(L) if k > a and re.match(r"^#{2,3} ", l))
    # keep a trailing "---" separator convention out of it
    L[a:b] = new_text.strip("\n").split("\n") + [""]
    t = "\n".join(L)

